package app.bosunarr.ui.art

import androidx.compose.ui.geometry.Offset

/*
 * Full-bleed versions of each [SeaScene] for [SeaBackdrop]. Coordinates are "stage" units: the subject is designed in
 * a 132-unit-wide stage whose horizon is at y = 80 and whose calm (text) zone starts at y = 104. [SeaBackdrop] scales
 * the stage to the screen, centres it, pins y = 80 to the horizon and draws sky, sea and wave rows across the full
 * width. Layers may reach far past the stage (x < 0 or > 132) so piers, ships and fog run to the screen edges at any
 * aspect ratio. `clip = true` here means "only above the horizon" (a setting sun, a lighthouse beam).
 * [Ink.Water] is a marker: the front water surface (at [FullSpec.water], filled with the sea gradient) is drawn at that
 * point, so hulls and posts dip into the sea and anything after it sits in front of the water.
 */
internal fun fullSceneSpec(scene: SeaScene): FullSpec = when (scene) {
    SeaScene.CalmSeas -> calmSeasFull()
    SeaScene.EmptyDock -> emptyDockFull()
    SeaScene.Horizon -> horizonFull()
    SeaScene.MessageBottle -> messageBottleFull()
    SeaScene.Spyglass -> spyglassFull()
    SeaScene.Harbor -> harborFull()
    SeaScene.Fog -> fogFull()
    SeaScene.Storm -> stormFull()
    SeaScene.Logbook -> logbookFull()
    SeaScene.SmoothSailing -> smoothSailingFull()
    SeaScene.Crew -> crewFull()
    SeaScene.Compass -> compassFull()
    SeaScene.SetSail -> setSailFull()
}

